def count_primes_in_range(a, b):
    def is_prime(num):
        if num < 2:
            return False
        for d in range(2, int(num ** 0.5) + 1):
            if num % d == 0:
                return False
        return True
    return sum(1 for val in range(a, b + 1) if is_prime(val))

