def min_case_changes_alternating(s):
    letters = []
    for ch in s:
        if ch.isalpha():
            letters.append(ch)
    if not letters:
        return 0
    start_upper_cost = 0
    start_lower_cost = 0
    for idx, ch in enumerate(letters):
        expects_upper = idx % 2 == 0
        actually_upper = ch.isupper()
        if expects_upper != actually_upper:
            start_upper_cost += 1
        else:
            start_lower_cost += 1
    return start_upper_cost if start_upper_cost < start_lower_cost else start_lower_cost

